<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <script src="https://polyfill.io/v3/polyfill.min.js?features=es6"></script>
    <script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;700&family=Times+New+Roman:wght@400;700&display=swap');

        body {
            margin: 0;
            padding: 0;
            font-family: "Roboto", "Helvetica", sans-serif;
            line-height: 1.4;
            color: #333;
            background: #fff;
            display: flex;
            justify-content: center;
            align-items: flex-start;
            min-height: 100vh;
        }

        .document-container {
            width: 100%;
            max-width: 800px;
            margin: 40px auto;
            padding: 20px;
            box-sizing: border-box;
            background: #fff;
            box-shadow: 0 0 20px rgba(0,0,0,0.1);
        }

        .page {
            page-break-after: always;
            margin-bottom: 40px;
            position: relative;
        }

        h1 {
            font-family: "Times New Roman", serif;
            font-size: 28px;
            font-weight: 700;
            text-align: center;
            margin: 20px 0 30px;
            color: #000;
        }

        h2 {
            font-family: "Times New Roman", serif;
            font-size: 24px;
            font-weight: 700;
            margin: 25px 0 15px;
            color: #000;
        }

        p {
            font-family: "Times New Roman", serif;
            font-size: 16px;
            margin: 8px 0;
        }

        .column-container {
            display: flex;
            gap: 40px;
            margin: 30px 0;
        }

        .column {
            flex: 1;
        }

        ul, ol {
            margin: 10px 0 10px 25px;
        }

        li {
            margin: 5px 0;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 15px 0;
        }

        th, td {
            border: 1px solid #000;
            padding: 8px;
            text-align: left;
        }

        .placeholder {
            width: 100%;
            height: 200px;
            background: #f0f0f0;
            border: 1px dashed #999;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #666;
            font-style: italic;
            margin: 20px 0;
            text-align: center;
        }

        .signature {
            width: 180px;
            height: 60px;
            border: 1px solid #333;
            margin: 15px 0;
        }

        .footer {
            text-align: center;
            font-size: 12px;
            color: #777;
            margin-top: 40px;
            border-top: 1px solid #ddd;
            padding-top: 15px;
        }
    </style>
</head>
<body>
    <div class="document-container">
        <!-- Page 1: Title and Header -->
        <div class="page">
            <h1>Sample Document Title</h1>
            <p style="text-align:center; font-style:italic;">Prepared by [Author Name]</p>

            <div class="column-container">
                <div class="column">
                    <p>Left column text starts here.</p>
                    <p>More text in the first column to demonstrate layout.</p>
                </div>
                <div class="column">
                    <p>Right column text continues with additional content for proper column alignment.</p>
                </div>
            </div>

            <p>Body paragraph that spans the full width.</p>

            <!-- Placeholder for a chart -->
            <div class="placeholder">[Chart: centered chart placeholder]</div>

            <p>Another paragraph below the chart.</p>

            <!-- Table -->
            <table>
                <thead>
                    <tr>
                        <th>Column A</th>
                        <th>Column B</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>Cell 1</td>
                        <td>Cell 2</td>
                    </tr>
                </tbody>
            </table>

            <p>Text under the table.</p>
        </div>

        <!-- Page 2 -->
        <div class="page">
            <h2>Section Heading</h2>
            <p>Second page content demonstrating continuation of the document.</p>

            <ul>
                <li>Bullet point 1</li>
                <li>Bullet point 2 with sub-item</li>
                <li>Another bullet point</li>
            </ul>

            <ol>
                <li>Ordered list item 1</li>
                <li>Ordered list item 2</li>
            </ol>

            <p>This paragraph includes <span style="font-weight:700;">bold</span> text and <span style="font-style:italic;">italic</span> text.</p>

            <!-- Signature placeholder -->
            <div style="margin:30px 0; text-align:center;">
                <div class="signature"></div>
                <p style="font-size:14px;">Signature block</p>
            </div>

            <p>Footer text on this page.</p>
        </div>

        <div class="footer">
            End of document • Page 2 of 2
        </div>
    </div>
</body>
</html>
```
